  window.findings=function(){migrate();const currentProject=project(),items=filteredFindings();return `<section class="page finding-workspace-v3" id="findings"><div class="section-head finding-page-head"><div><span class="eyebrow">${esc(inspection()?.id||'Prüfung')} · ${esc(currentProject?.client||'Auftraggeber')}</span><h2>Feststellungen</h2><p><b>${esc(currentProject?.name||'Aktuelles Objekt')}</b> · Feststellung, Maßnahme und Wirksamkeitsprüfung fachlich getrennt <button type="button" class="finding-info" title="Eine Feststellung beschreibt den Istzustand. Fristen und Verantwortliche gehören ausschließlich zu Maßnahmen; fachlich geschlossen wird erst nach bestätigter Wirksamkeit.">i</button></p></div><button class="primary" type="button" onclick="openFindingWorkspace(null,true)">+ Neue Feststellung</button></div>${summaryMarkup()}${filtersMarkup()}<div class="card finding-table-card"><table class="finding-table"><thead><tr><th>ID</th><th>Feststellung</th><th>Feststellungsart</th><th>Klassifikation</th><th>Bereich / System / Komponente</th><th>Status</th><th>Maßnahmen</th><th>Nächste Maßnahmenfrist</th><th>Verantwortlich</th><th>Aktionen</th></tr></thead><tbody>${items.map(rowMarkup).join('')}</tbody></table>${items.length?'':'<div class="finding-empty">Keine Feststellungen entsprechen den Filtern.</div>'}<div class="finding-mobile-list">${items.map(cardMarkup).join('')}</div></div></section>`}
