  function drawerMarkup(errors=[]){const f=draft,contextLocked=Boolean(f.questionId),docs=documentsOptions(f.attachmentIds||[]);return `<div class="finding-drawer ${drawerReadOnly?'is-readonly':''}" role="dialog" aria-modal="true" aria-labelledby="findingDrawerTitle"><header class="finding-drawer-head"><div><span class="eyebrow">${f.id?esc(f.id):'Neue Feststellung'} · ${esc(inspection()?.id||'Prüfung')}</span><h2 id="findingDrawerTitle">${f.id?(drawerReadOnly?'Feststellung ansehen':'Feststellung bearbeiten'):'Neue Feststellung'}</h2><p>Istzustand, Bewertung, Maßnahme und Wirksamkeit bleiben getrennt nachvollziehbar.</p></div><button type="button" class="modal-close" aria-label="Dialog schließen" onclick="closeFindingWorkspace()">×</button></header><form id="findingWorkspaceForm" onsubmit="event.preventDefault();saveFindingWorkspace('save')"><div class="finding-drawer-body">${errors.length?`<div class="finding-form-summary" role="alert"><b>${errors.length} Angaben prüfen</b><ul>${errors.map(e=>`<li>${esc(e.label)}</li>`).join('')}</ul></div>`:''}${f.migration?.reviewRequired?`<section class="migration-review"><b>Fachliche Zuordnung prüfen</b><p>${esc((f.migration.notes||[]).join(' '))}</p><button type="button" class="secondary" onclick="confirmFindingMigration()">Zuordnung als geprüft bestätigen</button></section>`:''}<section><h3>1 · Zuordnung</h3><div class="finding-form-grid"><label>Prüfung<input value="${esc(inspection()?.id||'')}" disabled></label><label>Prüfpunkt<select name="questionId" ${contextLocked?'disabled':''}>${option('','Ohne Prüfpunkt',f.questionId)}${(typeof questions!=='undefined'?questions:[]).map(q=>option(q[0],`${q[1]} · ${q[2]}`,f.questionId)).join('')}</select></label><label>Objekt *<input name="objectId" value="${esc(f.objectId)}" ${contextLocked?'readonly':''}>${fieldError('objectId',errors)}</label><label>Bereich / Raum<input name="area" value="${esc(f.area)}"></label><label>Anlage / System<input name="system" value="${esc(f.system)}"></label><label>Komponente *<input name="component" value="${esc(f.component)}" ${contextLocked&&f.component?'readonly':''}>${fieldError('component',errors)}</label></div></section><section><h3>2 · Feststellung und Bewertung</h3><div class="finding-form-grid"><label class="wide">Kurzer Titel *<input name="title" maxlength="160" value="${esc(f.title)}">${fieldError('title',errors)}</label><label>Feststellungsart *<select name="findingType">${option('','Bitte bewusst auswählen',f.findingType)}${FINDING_TYPES.map(v=>option(v,v,f.findingType)).join('')}</select>${fieldError('findingType',errors)}</label><label>Klassifikation *<select name="classification">${option('','Bitte bewusst auswählen',f.classification)}${CLASSIFICATIONS.map(v=>option(v,v,f.classification)).join('')}</select>${fieldError('classification',errors)}</label><label class="wide">Begründung der Klassifikation *<textarea name="classificationReason">${esc(f.classificationReason)}</textarea>${fieldError('classificationReason',errors)}</label><label class="wide">Detaillierter Istzustand *<textarea name="actualCondition">${esc(f.actualCondition)}</textarea>${fieldError('actualCondition',errors)}</label><label class="wide">Sollzustand / Anforderung *<textarea name="targetCondition">${esc(f.targetCondition)}</textarea>${fieldError('targetCondition',errors)}</label><label class="wide">Fachliche Bewertung<textarea name="evaluation">${esc(f.evaluation)}</textarea></label><label>Status<select name="status">${FINDING_STATUSES.map(v=>option(v,v,f.status)).join('')}</select>${fieldError('status',errors)}</label></div></section><section><h3>3 · Prüfgrundlage</h3><div class="finding-form-grid"><label>Art *<select name="basisType">${option('','Bitte auswählen',f.basis.type)}${BASIS_TYPES.map(v=>option(v,v,f.basis.type)).join('')}</select></label><label>Dokumentbezeichnung *<input name="basisDocument" value="${esc(f.basis.document)}">${fieldError('basisDocument',errors)}</label><label>Version / Ausgabedatum<input name="basisVersion" value="${esc(f.basis.version)}"></label><label>Abschnitt / Punkt / Seite *<input name="basisSection" value="${esc(f.basis.section)}"></label><label>Profil-Snapshot<input name="basisSnapshot" value="${esc(f.basis.profileSnapshot)}" readonly></label><label class="wide">Erläuterung<textarea name="basisNote">${esc(f.basis.note)}</textarea></label><label class="wide checkbox"><input type="checkbox" name="basisConfirmed" ${f.basis.confirmed?'checked':''}> Grundlage und Fundstelle wurden vom Benutzer bestätigt.</label></div></section><section><h3>4 · Nachweise</h3><p class="section-help">Fotos und Dateien werden mit Projekt, Erfassungszeitpunkt und erfassender Person verknüpft.</p><div class="evidence-picker">${docs}</div><label class="file-action">Foto oder Datei ergänzen<input type="file" accept="image/*,.pdf,.doc,.docx" multiple onchange="addFindingAttachments(this.files)"></label></section><section><h3>5 · Kommunikation</h3><div class="finding-form-grid"><label class="wide">Interner Hinweis<textarea name="internalNote" placeholder="Nur intern sichtbar; niemals automatisch im Bericht oder Kundenportal">${esc(f.internalNote)}</textarea></label><label class="wide">Kundentext<textarea name="customerText">${esc(f.customerCommunication.text)}</textarea></label><label>Freigabestatus Kundentext<select name="customerStatus">${CUSTOMER_STATUSES.map(v=>option(v,v,f.customerCommunication.status)).join('')}</select>${fieldError('customerStatus',errors)}</label><div class="approval-meta"><small>Freigegeben von</small><b>${esc(f.customerCommunication.approvedBy?.name||'Noch nicht freigegeben')}</b><small>${f.customerCommunication.approvedAt?new Intl.DateTimeFormat('de-AT',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Vienna'}).format(new Date(f.customerCommunication.approvedAt)):''}</small></div></div></section><section id="findingMeasuresSection"><div class="section-title"><div><h3>6 · Maßnahmen</h3><p class="section-help">Frist, Verantwortlichkeit und Bearbeitungsstatus werden ausschließlich hier geführt.</p></div><button type="button" class="secondary" onclick="addFindingDraftMeasure()">+ Maßnahme hinzufügen</button></div><div class="measure-editor-list">${f.measures.map((m,i)=>measureEditor(m,i,errors)).join('')||'<p class="finding-empty-inline">Noch keine Maßnahme zugeordnet.</p>'}</div></section><details class="history-panel"><summary>Version und Änderungshistorie</summary><div>${(f.history||[]).map(h=>`<p><b>${esc(h.field)}</b> · ${esc(h.actorName)} · ${new Intl.DateTimeFormat('de-AT',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Vienna'}).format(new Date(h.at))}<br><small>${esc(h.reason||'Änderung gespeichert')}</small></p>`).join('')||'<p>Noch keine Änderungen protokolliert.</p>'}</div></details></div><footer class="finding-drawer-actions"><button type="button" class="secondary" onclick="closeFindingWorkspace()">${drawerReadOnly?'Schließen':'Abbrechen'}</button>${drawerReadOnly?'':'<button type="button" class="secondary" onclick="saveFindingWorkspace(\'draft\')">Als Entwurf speichern</button><button type="submit" class="primary">Speichern</button><button type="button" class="primary" onclick="saveFindingWorkspace(\'measure\')">Speichern und Maßnahme anlegen</button>'}</footer></form></div>`}
  function renderDrawer(errors=[]){let backdrop=document.getElementById('findingWorkspaceBackdrop');if(!backdrop){backdrop=document.createElement('div');backdrop.id='findingWorkspaceBackdrop';backdrop.className='finding-drawer-backdrop';backdrop.addEventListener('mousedown',event=>{if(event.target===backdrop)closeFindingWorkspace()});document.body.appendChild(backdrop)}backdrop.innerHTML=drawerMarkup(errors);document.body.style.overflow='hidden';enhanceFormControls?.(backdrop);const drawer=backdrop.querySelector('.finding-drawer');if(drawerReadOnly)drawer.querySelectorAll('.finding-drawer-body input,.finding-drawer-body select,.finding-drawer-body textarea,.finding-drawer-body button').forEach(control=>control.disabled=true);drawer.addEventListener('keydown',trapFocus);setTimeout(()=>drawerReadOnly?drawer.querySelector('.modal-close')?.focus():drawer.querySelector('input:not([disabled]):not([readonly]),select:not([disabled]),textarea:not([disabled])')?.focus(),50)}
  function trapFocus(event){if(event.key!=='Tab')return;const controls=[...event.currentTarget.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,[tabindex="0"]')].filter(el=>el.offsetParent!==null);if(!controls.length)return;const first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
  window.openFindingWorkspace=function(id=null,editable=false,section=''){if(!window.requirePermission?.('findings',editable?'das Bearbeiten von Feststellungen':'das Öffnen von Feststellungen'))return;drawerOpener=document.activeElement;drawerReadOnly=!editable;const finding=id?findingById(id):null;draft=finding?draftFromFinding(finding):emptyFinding(typeof id==='object'?id:{});renderDrawer();if(section)setTimeout(()=>document.getElementById('findingMeasuresSection')?.scrollIntoView({block:'start'}),100)};
  window.openFindingDialog=()=>window.openFindingWorkspace(null,true);
