  window.addFindingDraftMeasure=function(){captureDraft();draft.measures.push({id:'',title:'',description:'',ownerId:'',ownerName:'',priority:'Normal',due:'',status:'Offen',completedAt:'',evidenceIds:[],internalNote:'',customerText:'',effectivenessReview:{result:'Prüfung ausständig',date:'',reviewer:null,description:'',evidenceIds:[],followUpFindingId:'',at:''},history:[],version:1});renderDrawer();setTimeout(()=>document.querySelector('.measure-editor:last-child input')?.focus(),50)};
